import React, { useState, useEffect, useRef } from 'react';
import { Card, Button, Alert, api } from '../App';

// Max 5 party slots per lot (P1-P5)
const MAX_SLOTS = 5;

export default function MarkingPage() {
  const [allParties,  setAllParties]  = useState([]);
  const [saleNos,     setSaleNos]     = useState([]);
  const [selParties,  setSelParties]  = useState([]); // ordered array [{id,name,code}]
  const [saleNo,      setSaleNo]      = useState('');
  const [partySearch, setPartySearch] = useState('');

  const [preview,      setPreview]      = useState([]);
  const [partyOrder,   setPartyOrder]   = useState([]); // [{key,party_id,name,code}]
  const [prices,       setPrices]       = useState({});
  const [skipRows,     setSkipRows]     = useState({});
  const [extraParties, setExtraParties] = useState({}); // catalogueId -> {code: {party_id,name,code}}
  const [addInputs,    setAddInputs]    = useState({});
  const [dupWarnings,  setDupWarnings]  = useState([]);
  const [loading,      setLoading]      = useState(false);
  const [saving,       setSaving]       = useState(false);
  const [alert,        setAlert]        = useState(null);

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(() => ({ data: [] })),
      api.get('/import/sale-numbers').catch(() => ({ data: [] }))
    ]).then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  const toggleParty = (p) => {
    setSelParties(prev =>
      prev.find(x => x.id === p.id)
        ? prev.filter(x => x.id !== p.id)
        : [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }]
    );
  };

  const filteredParties = allParties.filter(p =>
    p.party_name.toLowerCase().includes(partySearch.toLowerCase()) ||
    p.party_code.toLowerCase().includes(partySearch.toLowerCase())
  );

  const selectAll   = () => setSelParties(filteredParties.map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })));
  const deselectAll = () => setSelParties([]);

  const runPreview = async () => {
    if (!selParties.length || !saleNo) { setAlert({ msg: 'Select at least one party and sale number', type: 'error' }); return; }
    setLoading(true); setAlert(null); setDupWarnings([]);
    try {
      const r = await api.post('/marking/preview', { party_ids: selParties.map(p => p.id), sale_no: saleNo });
      setPreview(r.data.lots || []);
      setPartyOrder(r.data.parties || []);
      const init = {};
      (r.data.lots || []).forEach(row => { init[row.catalogue_id] = row.suggested_price || ''; });
      setPrices(init); setSkipRows({}); setExtraParties({}); setAddInputs({});
      if (!r.data.lots?.length)
        setAlert({ msg: 'No lots found. Check Party Master — ensure grades have Max Lots > 0, gardens are mapped, and filters match.', type: 'warning' });
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setLoading(false); }
  };

  // Get code suggestions for autocomplete
  const getCodeSuggestions = (val) => {
    if (!val || val.length < 1) return [];
    return allParties.filter(p => p.party_code.startsWith(val.toUpperCase())).slice(0, 6);
  };

  const addExtraParty = (catalogueId) => {
    const code = (addInputs[catalogueId] || '').trim().toUpperCase();
    if (!code) return;
    const p = allParties.find(x => x.party_code === code);
    if (!p) { setDupWarnings([`Party code "${code}" not found`]); return; }

    const lot = preview.find(x => x.catalogue_id === catalogueId);

    // Check if already in party_slots
    const inSlots = lot?.party_slots && Object.values(lot.party_slots).find(x => x.party_code === code);
    const inExtra = extraParties[catalogueId] && extraParties[catalogueId][code];
    if (inSlots || inExtra) {
      setDupWarnings([`⚠️ ${p.party_name} (${code}) already assigned to ${lot?.garden}/${lot?.grade}`]);
      return;
    }

    // Check total slots (main + extra) ≤ MAX_SLOTS
    const mainCount  = Object.keys(lot?.party_slots || {}).length;
    const extraCount = Object.keys(extraParties[catalogueId] || {}).length;
    if (mainCount + extraCount >= MAX_SLOTS) {
      setDupWarnings([`Max ${MAX_SLOTS} parties per lot. Cannot add more.`]);
      return;
    }

    setDupWarnings([]);
    setExtraParties(prev => ({
      ...prev,
      [catalogueId]: { ...(prev[catalogueId] || {}), [code]: { party_id: p.id, party_name: p.party_name, party_code: code } }
    }));
    setAddInputs(prev => ({ ...prev, [catalogueId]: '' }));
  };

  const handleAddKeyDown = (e, catalogueId) => {
    if (e.key === 'Enter') { e.preventDefault(); addExtraParty(catalogueId); }
  };

  const save = async () => {
    const markings = preview.filter(r => !skipRows[r.catalogue_id]).map(row => ({
      ...row,
      party_slots:   row.party_slots,
      extra_parties: extraParties[row.catalogue_id] || {},
      final_price:   prices[row.catalogue_id] || row.suggested_price,
    }));
    if (!markings.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings, sale_no: saleNo });
      setAlert({ msg: `✅ ${r.data.saved} markings saved.${r.data.duplicates ? ` ${r.data.duplicates} duplicates skipped.` : ''}`, type: 'success' });
      if (r.data.warnings?.length) setDupWarnings(r.data.warnings);
      setPreview([]);
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
    finally { setSaving(false); }
  };

  const activeCount = preview.filter(r => !skipRows[r.catalogue_id]).length;

  // For display: render P1-P5 columns always
  // Filled: show party code badge; Empty: show grey dash
  const renderPartySlots = (row) => {
    // Combine main party_slots + extra parties for this lot
    const allSlots = { ...(row.party_slots || {}), ...(extraParties[row.catalogue_id] || {}) };
    // Build ordered P1-P5 array
    const slots = [];
    for (let i = 1; i <= MAX_SLOTS; i++) {
      const key = `P${i}`;
      slots.push(allSlots[key] || null);
    }
    return slots;
  };

  const fmtDate = (d) => {
    if (!d) return '—';
    try { return new Date(d).toLocaleDateString('en-IN', { day:'2-digit', month:'2-digit' }).replace('/','/');}
    catch (e) { return d; }
  };

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>
        Select parties (unlimited). Each lot shows up to 5 party slots (P1–P5). Lots are fetched based on each party's mapping settings and grade Max Lots.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}
      {dupWarnings.length > 0 && (
        <div style={{ background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8, padding: '8px 14px', marginBottom: 12, fontSize: 12, color: '#92400e' }}>
          {dupWarnings.map((w, i) => <div key={i}>{w}</div>)}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '320px 1fr', gap: 16, marginBottom: 16 }}>
        {/* ── LEFT: Full party list (unlimited selection) ── */}
        <Card style={{ padding: 14 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 10 }}>
            Select Parties <span style={{ fontWeight: 400, fontSize: 12, color: '#888' }}>(unlimited)</span>
          </div>
          <input value={partySearch} onChange={e => setPartySearch(e.target.value)} placeholder="Search…"
            style={{ width: '100%', padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13, marginBottom: 8 }} />
          <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
            <Button size="sm" variant="outline" onClick={selectAll}   style={{ flex: 1, fontSize: 11 }}>✓ Select All</Button>
            <Button size="sm" variant="outline" onClick={deselectAll} style={{ flex: 1, fontSize: 11 }}>✕ Clear</Button>
          </div>
          <div style={{ maxHeight: 460, overflowY: 'auto', border: '1px solid #f0f4f8', borderRadius: 6 }}>
            {filteredParties.map(p => {
              const sel = !!selParties.find(x => x.id === p.id);
              const idx = selParties.findIndex(x => x.id === p.id);
              return (
                <div key={p.id} onClick={() => toggleParty(p)}
                  style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', cursor: 'pointer',
                    background: sel ? '#dbeafe' : '#fff', borderBottom: '1px solid #f0f4f8', userSelect: 'none' }}>
                  <div style={{ width: 18, height: 18, borderRadius: 3, border: `2px solid ${sel ? '#1a3c5e' : '#cbd5e0'}`,
                    background: sel ? '#1a3c5e' : '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    {sel && <span style={{ color: '#fff', fontSize: 11, fontWeight: 700 }}>✓</span>}
                  </div>
                  <div style={{ flex: 1 }}>
                    <span style={{ fontWeight: 700, fontSize: 12, color: '#1a3c5e' }}>[{p.party_code}]</span>
                    <span style={{ fontSize: 12, marginLeft: 5 }}>{p.party_name}</span>
                  </div>
                  {sel && <span style={{ background: '#1a3c5e', color: '#fff', fontSize: 10, fontWeight: 700, padding: '1px 6px', borderRadius: 99 }}>P{idx+1}</span>}
                </div>
              );
            })}
          </div>
          {selParties.length > 0 && (
            <div style={{ marginTop: 8, fontSize: 11, color: '#1a3c5e', background: '#eff6ff', padding: '6px 10px', borderRadius: 6, lineHeight: 1.6 }}>
              <b>{selParties.length} selected:</b><br/>
              {selParties.map((p, i) => `P${i+1}:${p.party_code}`).join(' · ')}
            </div>
          )}
        </Card>

        {/* ── RIGHT: Sale + Action ── */}
        <Card style={{ padding: 16, alignSelf: 'start' }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 12 }}>Sale & Preview</div>
          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>Sale Number *</label>
              <select value={saleNo} onChange={e => setSaleNo(e.target.value)}
                style={{ padding: '8px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
                <option value="">Select sale…</option>
                {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
              </select>
            </div>
            <Button onClick={runPreview} disabled={loading || !selParties.length || !saleNo} variant="primary">
              {loading ? '⏳ Fetching…' : '🔍 Preview Lots'}
            </Button>
            {preview.length > 0 && (
              <Button onClick={save} disabled={saving || activeCount === 0} variant="success">
                {saving ? 'Saving…' : `💾 Save ${activeCount} Markings`}
              </Button>
            )}
          </div>

          {preview.length > 0 && (
            <div style={{ marginTop: 10, fontSize: 12, color: '#555' }}>
              <b>{preview.length}</b> lots · <b style={{ color: '#1a7a4a' }}>{activeCount}</b> active
            </div>
          )}

          <div style={{ marginTop: 12, padding: '8px 12px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 6, fontSize: 11, color: '#92400e' }}>
            <b>Slot logic:</b> Each lot shows P1–P5. P slots are filled only for parties whose mapping includes that lot's garden+grade.
            Remaining slots show grey. You can manually add up to 5 parties per lot using the + column.
          </div>
        </Card>
      </div>

      {/* ── MARKING TABLE ── */}
      {preview.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '10px 16px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>Marking List — Sale #{saleNo}</div>
            <div style={{ fontSize: 12, opacity: 0.8 }}>{preview.length} lots · max 5 slots/lot</div>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', width: 40 }}>Skip</th>
                  {/* Fixed P1-P5 columns */}
                  {[1,2,3,4,5].map(n => (
                    <th key={n} style={{ padding: '8px 6px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', background: '#1a3c5e', minWidth: 60 }}>
                      P{n}
                    </th>
                  ))}
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Bro</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Lot</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap', minWidth: 130 }}>Garden</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Grd</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap', minWidth: 120 }}>Rate (Min-Max)</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>Qty</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>NWt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'center',fontWeight: 600, whiteSpace: 'nowrap' }}>GP Dt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap', minWidth: 120 }}>+ Add</th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  let lastBroker = null;
                  return preview.map((row, i) => {
                    const skip = !!skipRows[row.catalogue_id];
                    const brokerHeader = row.broker !== lastBroker;
                    lastBroker = row.broker;
                    const slots = renderPartySlots(row);
                    const inputVal = addInputs[row.catalogue_id] || '';
                    const suggestions = getCodeSuggestions(inputVal);

                    const fmtRate = () => {
                      const mn = row.min_deal_price, mx = row.max_deal_price;
                      if (!mn && !mx) return '—';
                      if (mn && mx && Math.abs(parseFloat(mn)-parseFloat(mx)) > 0.5)
                        return `${Number(mn).toFixed(0)}-${Number(mx).toFixed(0)}`;
                      return `${Number(mn||mx).toFixed(0)}/-`;
                    };

                    return (
                      <React.Fragment key={row.catalogue_id}>
                        {brokerHeader && (
                          <tr>
                            <td colSpan={15}
                              style={{ background: '#e8f0fe', padding: '5px 10px', fontWeight: 700, fontSize: 12, color: '#1a3c5e', borderBottom: '1px solid #c7d2fe' }}>
                              Broker: {row.broker}
                            </td>
                          </tr>
                        )}
                        <tr style={{ borderBottom: '1px solid #f0f4f8', background: skip ? '#fff5f5' : (i % 2 === 0 ? '#fff' : '#fafbfc'), opacity: skip ? 0.4 : 1 }}>
                          <td style={{ padding: '5px 6px', textAlign: 'center' }}>
                            <input type="checkbox" checked={skip}
                              onChange={() => setSkipRows(s => ({ ...s, [row.catalogue_id]: !s[row.catalogue_id] }))} />
                          </td>

                          {/* P1-P5 fixed slots */}
                          {slots.map((slot, si) => (
                            <td key={si} style={{ padding: '5px 6px', textAlign: 'center' }}>
                              {slot
                                ? <span style={{ background: '#1a3c5e', color: '#fff', padding: '2px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{slot.party_code}</span>
                                : <span style={{ color: '#d1d5db', fontSize: 12 }}>—</span>
                              }
                            </td>
                          ))}

                          <td style={{ padding: '5px 8px', fontWeight: 600, color: '#555' }}>{row.broker}</td>
                          <td style={{ padding: '5px 8px', fontFamily: 'monospace', fontSize: 11, color: '#1a3c5e', fontWeight: 700 }}>{row.lot_no}</td>
                          <td style={{ padding: '5px 8px', fontWeight: 700, color: '#1a3c5e', maxWidth: 160, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{row.garden}</td>
                          <td style={{ padding: '5px 8px' }}>
                            <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{row.grade}</span>
                          </td>
                          <td style={{ padding: '5px 8px', textAlign: 'right', fontWeight: 600, color: '#1a3c5e' }}>{fmtRate()}</td>
                          <td style={{ padding: '5px 8px', textAlign: 'right', fontWeight: 600 }}>{row.bags || '—'}</td>
                          <td style={{ padding: '5px 8px', textAlign: 'right' }}>{row.net_wt || '—'}</td>
                          <td style={{ padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#888' }}>
                            {row.gp_date ? fmtDate(row.gp_date) : '—'}
                          </td>

                          {/* Add party input */}
                          <td style={{ padding: '5px 8px' }}>
                            <div style={{ position: 'relative', display: 'inline-block' }}>
                              <div style={{ display: 'flex', gap: 3, alignItems: 'center' }}>
                                <input
                                  value={inputVal}
                                  onChange={e => setAddInputs(prev => ({ ...prev, [row.catalogue_id]: e.target.value.toUpperCase() }))}
                                  onKeyDown={e => handleAddKeyDown(e, row.catalogue_id)}
                                  placeholder="Code"
                                  maxLength={5}
                                  title="Type party code + Enter"
                                  style={{ width: 52, padding: '3px 5px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 11, fontFamily: 'monospace', textTransform: 'uppercase' }}
                                />
                                <button onClick={() => addExtraParty(row.catalogue_id)}
                                  style={{ padding: '3px 7px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 5, cursor: 'pointer', fontSize: 11, fontWeight: 700 }}>+</button>
                              </div>
                              {suggestions.length > 0 && inputVal.length > 0 && (
                                <div style={{ position: 'absolute', top: '100%', left: 0, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 6, zIndex: 999, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', minWidth: 150 }}>
                                  {suggestions.map(s => (
                                    <div key={s.id}
                                      onMouseDown={e => { e.preventDefault(); setAddInputs(prev => ({ ...prev, [row.catalogue_id]: s.party_code })); setTimeout(() => addExtraParty(row.catalogue_id), 50); }}
                                      style={{ padding: '6px 10px', cursor: 'pointer', fontSize: 12, borderBottom: '1px solid #f0f4f8' }}
                                      onMouseEnter={e => e.currentTarget.style.background = '#f0f8ff'}
                                      onMouseLeave={e => e.currentTarget.style.background = '#fff'}>
                                      <b>{s.party_code}</b> — {s.party_name}
                                    </div>
                                  ))}
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      </React.Fragment>
                    );
                  });
                })()}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}
